
CREATE TEMP TABLE _ufes_editorial_guides ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($facedu$[{"code":"LCE13698","focus":"Libras como língua visual-espacial, direitos linguísticos e educação inclusiva.","steps":["Distinguir gramática de Libras, gestos e português sinalizado.","Examinar história e diversidade sociolinguística das comunidades surdas.","Analisar acessibilidade e participação de estudantes surdos sem presumir perfis homogéneos."],"activity":"Construir lista de verificação de acessibilidade para uma aula de inglês; prever validação de sinais e recursos por profissionais de Libras.","questions":["Por que a Libras não é uma tradução gestual do português?","Como consultar a comunidade surda na criação de materiais?"]},{"code":"LET10553","focus":"Português como língua adicional, géneros comunicativos e diversidade linguística.","steps":["Identificar objetivos e perfis de uso da língua dos aprendentes.","Selecionar géneros textuais autênticos adequados ao contexto.","Desenhar atividades integradas de compreensão, interação e escrita."],"activity":"Criar uma microsequência comunicativa para aprendentes iniciantes de português, com objetivos e rubrica de feedback.","questions":["Como uma análise de necessidades orienta a escolha dos textos?","Como respeitar variedades regionais do português?"]},{"code":"LET13924","focus":"Teorias e prática inicial de tradução entre diferentes línguas e públicos.","steps":["Comparar finalidade, destinatário e contexto de traduções.","Analisar equivalência pragmática e referências culturais.","Discutir responsabilidade, autoria, licenças e limites da tradução automática."],"activity":"Traduzir um excerto breve em domínio público para dois públicos e justificar cinco escolhas.","questions":["Por que tradução literal nem sempre comunica a intenção?","Como identificar erros semanticamente relevantes numa tradução automática?"]},{"code":"LET13929","focus":"Tradução e mediação linguística como recursos da docência de inglês.","steps":["Relacionar mediação plurilingue e aprendizagem de línguas.","Investigar atividades de reformulação entre públicos e géneros.","Desenvolver feedback baseado em adequação comunicativa e não em literalidade."],"activity":"Planear atividade de mediação bilíngue para uma turma de inglês, com critérios de êxito inclusivos.","questions":["Em que situação traduzir facilita a comunicação?","O que caracteriza um feedback de tradução formativo?"]},{"code":"LET13938","focus":"Tradução, comparação cultural, revisão e uso crítico de tecnologias.","steps":["Comparar abordagens funcionais e orientadas para a forma.","Analisar decisões em textos técnicos, culturais e literários.","Rever propostas automáticas atentando a sentido, sigilo e direitos."],"activity":"Preparar tradução comentada de texto em domínio público e relatório sobre três problemas de revisão.","questions":["Como distinguir fluência superficial de precisão?","Como justificar escolhas perante públicos distintos?"]},{"code":"LET13940","focus":"Significado, referência, interpretação e ação comunicativa na filosofia da linguagem.","steps":["Distinguir referência, sentido e contexto de enunciação.","Analisar pedidos, promessas e outros atos de fala em situações reais.","Investigar pressupostos e ambiguidades relevantes para ensino de línguas."],"activity":"Anotar cinco frases em inglês e português, separando sentido expresso, inferido e dependente do contexto.","questions":["Por que duas frases semelhantes podem agir de modo diferente?","Quando conhecer vocabulário é insuficiente para interpretar um enunciado?"]},{"code":"LET13941","focus":"Linguística aplicada crítica: identidade, ideologia e desigualdade no ensino de línguas.","steps":["Identificar silenciamentos e vozes dominantes em materiais públicos.","Analisar escolhas de variedade linguística e representação cultural.","Propor estratégias pedagógicas de análise crítica sem estereótipos."],"activity":"Comparar dois recursos educativos públicos e justificar ajustes que ampliem representatividade e participação.","questions":["Onde aparecem relações de poder em materiais aparentemente neutros?","Como evitar generalizações ao estudar discursos e identidades?"]},{"code":"LET13958","focus":"Inglês para fins específicos com análise de necessidades e tarefas autênticas.","steps":["Mapear funções comunicativas de um setor ou comunidade.","Investigar géneros, vocabulário e práticas de interação específicas.","Definir avaliação vinculada a tarefas concretas."],"activity":"Projetar miniaula de inglês para atendimento turístico, com três necessidades e uma tarefa observável.","questions":["Por que a análise de necessidades precede a gramática?","Como verificar que exemplos são autênticos e relevantes?"]},{"code":"LET13961","focus":"Literatura medieval em inglês: contexto histórico, transmissão e tradução.","steps":["Contextualizar autoria, manuscritos e circulação cultural.","Comparar texto medieval, edição modernizada e tradução quando disponíveis.","Interpretar poder, religião e representação sem anacronismos."],"activity":"Comparar passagem medieval de acesso legítimo com uma modernização, anotando mudanças de voz e escolhas editoriais.","questions":["Como uma edição afeta a leitura de um texto antigo?","Quais interpretações seriam anacrónicas?"]},{"code":"LET13969","focus":"Relações entre literatura, cinema, teatro, música e artes visuais.","steps":["Identificar recursos de expressão específicos de cada suporte.","Comparar adaptação e interpretação sem reduzir a qualidade à fidelidade.","Investigar autoria, receção e limites de reprodução de imagens."],"activity":"Analisar três decisões narrativas numa adaptação audiovisual de obra em domínio público.","questions":["Como o suporte transforma voz e tempo narrativo?","Como citar obras sem reproduzir conteúdo protegido?"]},{"code":"LET13971","focus":"Diversidade histórica e estética das literaturas de língua portuguesa.","steps":["Reconhecer contextos culturais distintos de produção literária lusófona.","Comparar vozes narrativas, formas e estratégias de representação.","Analisar circulação editorial e formação de cânones."],"activity":"Escrever comparação entre dois textos de acesso legítimo de comunidades lusófonas distintas, com fontes.","questions":["O que se perde ao tratar a literatura lusófona como uma única tradição?","Que instituições influenciam a escolha de um cânone?"]},{"code":"LET13972","focus":"Literatura infantil e juvenil, mediação de leitura e pluralidade de interpretações.","steps":["Considerar relações entre texto, ilustração, público e contexto.","Avaliar diversidade e acessibilidade de obras selecionadas.","Propor rodas de leitura que valorizem respostas interpretativas abertas."],"activity":"Preparar roteiro de conversa literária baseado num conto de acesso legítimo, com perguntas e adaptação acessível.","questions":["Como reconhecer valor literário para além da moralização?","Como acolher leituras diferentes de uma obra?"]},{"code":"LET13973","focus":"Cânones internacionais, crítica literária e abordagens interpretativas.","steps":["Comparar interpretações formais, históricas e culturais.","Investigar quem define legitimidade literária e como isso muda.","Identificar ausências e perspectivas críticas minoritárias."],"activity":"Produzir duas leituras curtas do mesmo poema em domínio público a partir de perspectivas distintas.","questions":["Por que um cânone não é neutro?","O que cada abordagem crítica evidencia ou ignora?"]},{"code":"LET13974","focus":"Literatura produzida no Espírito Santo e memória cultural capixaba.","steps":["Pesquisar obras e documentação catalogadas pelo NEPLES/UFES.","Relacionar produção literária regional a circulação e contexto históricos.","Diferenciar evidência bibliográfica de juízos sobre representatividade."],"activity":"Organizar bibliografia comentada de quatro itens do acervo NEPLES, com autores, datas, fontes e perguntas.","questions":["Quais fontes sustentam uma afirmação sobre história literária capixaba?","Por que a literatura regional não constitui um único estilo?"]},{"code":"TEP13690","focus":"Educação das relações étnico-raciais e práticas pedagógicas antirracistas.","steps":["Reconhecer estereótipos e silenciamentos em materiais escolares.","Debater inclusão e desigualdade estrutural no contexto da educação brasileira.","Desenvolver critérios de seleção de textos e atividades sem reproduzir preconceitos."],"activity":"Produzir grelha de análise antirracista para dois materiais públicos e propor melhorias fundamentadas.","questions":["Qual a diferença entre celebrar diversidade e enfrentar racismo estrutural?","Como criticar estereótipos sem os reforçar?"]}]$facedu$::jsonb)
AS r(code text,focus text,steps jsonb,activity text,questions jsonb);
DO $a$ BEGIN
 IF (SELECT count(*) FROM _ufes_editorial_guides)<>15 OR
 (SELECT count(DISTINCT code) FROM _ufes_editorial_guides)<>15 OR
 EXISTS(SELECT 1 FROM _ufes_editorial_guides g LEFT JOIN facodi.curricular_units u
  ON u.code=g.code AND u.course_id=md5('facodi:ufes:83:2019:course')::uuid AND u.published
  WHERE u.id IS NULL OR jsonb_array_length(g.steps)<>3 OR jsonb_array_length(g.questions)<>2
   OR btrim(coalesce(u.description_html,''))<>'')
 THEN RAISE EXCEPTION 'Unexpected data, duplicate, or previous editorial material — stop'; END IF;
END $a$;
UPDATE facodi.curricular_units u SET
 description_html=
 '<section><h2>Guia de estudo FACODI — complementar</h2>'||
 '<p><strong>Foco:</strong> '||g.focus||'</p>'||
 '<p>Roteiro editorial elaborado pela FACODI a partir do tema da UC e dos recursos externos já selecionados. Não substitui a ementa, bibliografia, plano de aula ou avaliação oficiais da UFES.</p>'||
 '<h3>Sequência de aprendizagem proposta</h3><ol>'||
 (SELECT string_agg('<li>'||x.v||'</li>','' ORDER BY x.n)
  FROM jsonb_array_elements_text(g.steps) WITH ORDINALITY x(v,n))||
 '</ol><h3>Atividade prática</h3><p>'||g.activity||'</p>'||
 '<h3>Autoavaliação</h3><ul>'||
 (SELECT string_agg('<li>'||x.v||'</li>','' ORDER BY x.n)
  FROM jsonb_array_elements_text(g.questions) WITH ORDINALITY x(v,n))||
 '</ul><p>Para requisitos académicos e programa oficial, consulte o PPC 2019 da UFES indicado na ficha da unidade.</p></section>',
 metadata=u.metadata||jsonb_build_object(
 'facodi_study_guide_version','2026-11-15',
 'facodi_original_study_guide',true,'official_university_syllabus',false,
 'authored_by','FACODI editorial','faculty_approval',false,
 'source_basis','title_of_UFES_curricular_unit_and_curated_resources',
 'editorial_review','original_facodi_proposal',
 'guide_focus',g.focus,'guide_steps',g.steps,
 'self_assessment_questions',g.questions)
FROM _ufes_editorial_guides g
WHERE u.code=g.code AND u.course_id=md5('facodi:ufes:83:2019:course')::uuid
AND btrim(coalesce(u.description_html,''))='';
DO $verify$ BEGIN
IF (SELECT count(*) FROM facodi.curricular_units u
WHERE u.course_id=md5('facodi:ufes:83:2019:course')::uuid
AND u.code IN (SELECT code FROM _ufes_editorial_guides)
AND u.description_html LIKE '%Guia de estudo FACODI%'
AND u.metadata->>'facodi_study_guide_version'='2026-11-15')<>15
THEN RAISE EXCEPTION 'Expected 15 published study guides'; END IF;
END $verify$;